19	package org.apache.hadoop.util;
20	
21	import java.lang.ref.WeakReference;
22	import java.util.Iterator;
23	import java.util.Map;
24	import java.util.concurrent.ConcurrentHashMap;
25	import java.util.concurrent.atomic.AtomicLong;
26	import java.util.function.Consumer;
27	import java.util.function.Function;
28	
29	import javax.annotation.Nullable;
30	
31	import org.slf4j.Logger;
32	import org.slf4j.LoggerFactory;
33	
34	import org.apache.hadoop.classification.InterfaceAudience;
35	import org.apache.hadoop.fs.store.LogExactlyOnce;
36	
37	import static java.util.Objects.requireNonNull;
38	
39	/**
40	 * A map of keys type K to objects of type V which uses weak references,
41	 * so does lot leak memory through long-lived references
42	 * <i>at the expense of losing references when GC takes place.</i>.
43	 *
44	 * This class is intended be used instead of ThreadLocal storage when
45	 * references are to be cleaned up when the instance holding.
46	 * In this use case, the key is the Long key.
47	 *
48	 * Concurrency.
49	 * The class assumes that map entries are rarely contended for when writing,
50	 * and that not blocking other threads is more important than atomicity.
51	 * - a ConcurrentHashMap is used to map keys to weak references, with
52	 *   all its guarantees.
53	 * - there is no automatic pruning.
54	 * - see {@link #create(Object)} for the concurrency semantics on entry creation.
55	 */
56	@InterfaceAudience.Private
57	public class WeakReferenceMap<K, V> {
58	
59	  private static final Logger LOG =
60	      LoggerFactory.getLogger(WeakReferenceMap.class);
61	
62	  /**
63	   * The reference map.
64	   */
65	  private final Map<K, WeakReference<V>> map = new ConcurrentHashMap<>();
66	
67	  /**
68	   * Supplier of new instances.
69	   */
70	  private final Function<? super K, ? extends V> factory;
71	
72	  /**
73	   * Nullable callback when a get on a key got a weak reference back.
74	   * The assumption is that this is for logging/stats, which is why
75	   * no attempt is made to use the call as a supplier of a new value.
76	   */
77	  private final Consumer<? super K> referenceLost;
78	
79	  /**
80	   * Counter of references lost.
81	   */
82	  private final AtomicLong referenceLostCount = new AtomicLong();
83	
84	  /**
85	   * Counter of entries created.
86	   */
87	  private final AtomicLong entriesCreatedCount = new AtomicLong();
88	
89	  /**
90	   * Log to report loss of a reference during the create phase, which
91	   * is believed to be a cause of HADOOP-18456.
92	   */
93	  private final LogExactlyOnce referenceLostDuringCreation = new LogExactlyOnce(LOG);
94	
95	  /**
96	   * instantiate.
97	   * @param factory supplier of new instances
98	   * @param referenceLost optional callback on lost references.
99	   */
100	  public WeakReferenceMap(
101	      Function<? super K, ? extends V> factory,
102	      @Nullable final Consumer<? super K> referenceLost) {
103	
104	    this.factory = requireNonNull(factory);
105	    this.referenceLost = referenceLost;
106	  }
107	
108	  @Override
109	  public String toString() {
110	    return "WeakReferenceMap{" +
111	        "size=" + size() +
112	        ", referenceLostCount=" + referenceLostCount +
113	        ", entriesCreatedCount=" + entriesCreatedCount +
114	        '}';
115	  }
116	
117	  /**
118	   * Map size.
119	   * @return the current map size.
120	   */
121	  public int size() {
122	    return map.size();
123	  }
124	
125	  /**
126	   * Clear all entries.
127	   */
128	  public void clear() {
129	    map.clear();
130	  }
131	
132	  /**
133	   * look up the value, returning the possibly empty weak reference
134	   * to a value, or null if no value was found.
135	   * @param key key to look up
136	   * @return null if there is no entry, a weak reference if found
137	   */
138	  public WeakReference<V> lookup(K key) {
139	    return map.get(key);
140	  }
141	
142	  /**
143	   * Get the value, creating if needed.
144	   * @param key key.
145	   * @return an instance.
146	   */
147	  public V get(K key) {
148	    final WeakReference<V> currentWeakRef = lookup(key);
149	    // resolve it, after which if not null, we have a strong reference
150	    V strongVal = resolve(currentWeakRef);
151	    if (strongVal != null) {
152	      // all good.
153	      return  strongVal;
154	    }
155	
156	    // here, either currentWeakRef was null, or its reference was GC'd.
157	    if (currentWeakRef != null) {
158	      // garbage collection removed the reference.
159	
160	      // explicitly remove the weak ref from the map if it has not
161	      // been updated by this point
162	      // this is here just for completeness.
163	      map.remove(key, currentWeakRef);
164	
165	      // log/report the loss.
166	      noteLost(key);
167	    }
168	
169	    // create a new value and add it to the map
170	    return create(key);
171	  }
172	
173	  /**
174	   * Create a new instance under a key.
175	   * <p>
176	   * The instance is created, added to the map and then the
177	   * map value retrieved.
178	   * This ensures that the reference returned is that in the map,
179	   * even if there is more than one entry being created at the same time.
180	   * If that race does occur, it will be logged the first time it happens
181	   * for this specific map instance.
182	   * <p>
183	   * HADOOP-18456 highlighted the risk of a concurrent GC resulting a null
184	   * value being retrieved and so returned.
185	   * To prevent this:
186	   * <ol>
187	   *   <li>A strong reference is retained to the newly created instance
188	   *       in a local variable.</li>
189	   *   <li>That variable is used after the resolution process, to ensure
190	   *       the JVM doesn't consider it "unreachable" and so eligible for GC.</li>
191	   *   <li>A check is made for the resolved reference being null, and if so,
192	   *       the put() is repeated</li>
193	   * </ol>
194	   * @param key key
195	   * @return the created value
196	   */
197	  public V create(K key) {
198	    entriesCreatedCount.incrementAndGet();
199	    /*
200	     Get a strong ref so even if a GC happens in this method the reference is not lost.
201	     It is NOT enough to have a reference in a field, it MUST be used
202	     so as to ensure the reference isn't optimized away prematurely.
203	     "A reachable object is any object that can be accessed in any potential continuing
204	      computation from any live thread."
205	    */
206	
207	    final V strongRef = requireNonNull(factory.apply(key),
208	        "factory returned a null instance");
209	    V resolvedStrongRef;
210	    do {
211	      WeakReference<V> newWeakRef = new WeakReference<>(strongRef);
212	
213	      // put it in the map
214	      map.put(key, newWeakRef);
215	
216	      // get it back from the map
217	      WeakReference<V> retrievedWeakRef = map.get(key);
218	      // resolve that reference, handling the situation where somehow it was removed from the map
219	      // between the put() and the get()
220	      resolvedStrongRef = resolve(retrievedWeakRef);
221	      if (resolvedStrongRef == null) {
222	        referenceLostDuringCreation.warn("reference to %s lost during creation", key);
223	        noteLost(key);
224	      }
225	    } while (resolvedStrongRef == null);
226	
227	    // note if there was any change in the reference.
228	    // as this forces strongRef to be kept in scope
229	    if (strongRef != resolvedStrongRef) {
230	      LOG.debug("Created instance for key {}: {} overwritten by {}",
231	          key, strongRef, resolvedStrongRef);
232	    }
233	
234	    return resolvedStrongRef;
235	  }
236	
237	  /**
238	   * Put a value under the key.
239	   * A null value can be put, though on a get() call
240	   * a new entry is generated
241	   *
242	   * @param key key
243	   * @param value value
244	   * @return any old non-null reference.
245	   */
246	  public V put(K key, V value) {
247	    return resolve(map.put(key, new WeakReference<>(value)));
248	  }
249	
250	  /**
251	   * Remove any value under the key.
252	   * @param key key
253	   * @return any old non-null reference.
254	   */
255	  public V remove(K key) {
256	    return resolve(map.remove(key));
257	  }
258	
259	  /**
260	   * Does the map have a valid reference for this object?
261	   * no-side effects: there's no attempt to notify or cleanup
262	   * if the reference is null.
263	   * @param key key to look up
264	   * @return true if there is a valid reference.
265	   */
266	  public boolean containsKey(K key) {
267	    final WeakReference<V> current = lookup(key);
268	    return resolve(current) != null;
269	  }
270	
271	  /**
272	   * Given a possibly null weak reference, resolve
273	   * its value.
274	   * @param r reference to resolve
275	   * @return the value or null
276	   */
277	  protected V resolve(WeakReference<V> r) {
278	    return r == null ? null : r.get();
279	  }
280	
281	  /**
282	   * Prune all null weak references, calling the referenceLost
283	   * callback for each one.
284	   *
285	   * non-atomic and non-blocking.
286	   * @return the number of entries pruned.
287	   */
288	  public int prune() {
289	    int count = 0;
290	    final Iterator<Map.Entry<K, WeakReference<V>>> it = map.entrySet().iterator();
291	    while (it.hasNext()) {
292	      final Map.Entry<K, WeakReference<V>> next = it.next();
293	      if (next.getValue().get() == null) {
294	        it.remove();
295	        count++;
296	        noteLost(next.getKey());
297	      }
298	    }
299	    return count;
300	  }
301	
302	  /**
303	   * Notify the reference lost callback.
304	   * @param key key of lost reference
305	   */
306	  private void noteLost(final K key) {
307	    // increment local counter
308	    referenceLostCount.incrementAndGet();
309	
310	    // and call any notification function supplied in the constructor
311	    if (referenceLost != null) {
312	      referenceLost.accept(key);
313	    }
314	  }
315	
316	  /**
317	   * Get count of references lost as detected
318	   * during prune() or get() calls.
319	   * @return count of references lost
320	   */
321	  public final long getReferenceLostCount() {
322	    return referenceLostCount.get();
323	  }
324	
325	  /**
326	   * Get count of entries created on demand.
327	   * @return count of entries created
328	   */
329	  public final long getEntriesCreatedCount() {
330	    return entriesCreatedCount.get();
331	  }
332	}
