19	package org.apache.hadoop.fs.impl;
20	
21	import java.lang.ref.WeakReference;
22	import java.util.function.Consumer;
23	import java.util.function.Function;
24	import javax.annotation.Nullable;
25	
26	import org.apache.hadoop.util.WeakReferenceMap;
27	
28	import static java.util.Objects.requireNonNull;
29	
30	/**
31	 * A WeakReferenceMap for threads.
32	 * @param <V> value type of the map
33	 */
34	public class WeakReferenceThreadMap<V> extends WeakReferenceMap<Long, V> {
35	
36	  public WeakReferenceThreadMap(final Function<? super Long, ? extends V> factory,
37	      @Nullable final Consumer<? super Long> referenceLost) {
38	    super(factory, referenceLost);
39	  }
40	
41	  /**
42	   * Get the value for the current thread, creating if needed.
43	   * @return an instance.
44	   */
45	  public V getForCurrentThread() {
46	    return get(currentThreadId());
47	  }
48	
49	  /**
50	   * Remove the reference for the current thread.
51	   * @return any reference value which existed.
52	   */
53	  public V removeForCurrentThread() {
54	    return remove(currentThreadId());
55	  }
56	
57	  /**
58	   * Get the current thread ID.
59	   * @return thread ID.
60	   */
61	  public long currentThreadId() {
62	    return Thread.currentThread().getId();
63	  }
64	
65	  /**
66	   * Set the new value for the current thread.
67	   * @param newVal new reference to set for the active thread.
68	   * @return the previously set value, possibly null
69	   */
70	  public V setForCurrentThread(V newVal) {
71	    requireNonNull(newVal);
72	    long id = currentThreadId();
73	
74	    // if the same object is already in the map, just return it.
75	    WeakReference<V> existingWeakRef = lookup(id);
76	
77	    // The looked up reference could be one of
78	    // 1. null: nothing there
79	    // 2. valid but get() == null : reference lost by GC.
80	    // 3. different from the new value
81	    // 4. the same as the old value
82	    if (resolve(existingWeakRef) == newVal) {
83	      // case 4: do nothing, return the new value
84	      return newVal;
85	    } else {
86	      // cases 1, 2, 3: update the map and return the old value
87	      return put(id, newVal);
88	    }
89	
90	  }
91	
92	}
