71	/**
72	 * Thread management for the active audit.
73	 * This should be created by whatever wants to have active
74	 * audit span tracking.
75	 *
76	 * It creates and starts the actual
77	 * {@link OperationAuditor} for auditing.
78	 * It then stores the thread-local span and returns a wrapping
79	 * span.
80	 *
81	 * When the wrapper is closed/deactivated it
82	 * will deactivate the wrapped span and then
83	 * switch the active span to the unbounded span.
84	 *
85	 * The inner class {@link AWSAuditEventCallbacks} is returned
86	 * as a request handler in {@link #createRequestHandlers()};
87	 * this forwards all requests to the outer {@code ActiveAuditManagerS3A},
88	 * which then locates the active span and forwards the request.
89	 * If any such invocation raises an {@link AuditFailureException}
90	 * then the IOStatistics counter for {@code AUDIT_FAILURE}
91	 * is incremented.
92	 *
93	 * Uses a {@link WeakReferenceThreadMap} to store the active span
94	 * of each thread, rather than a {@code ThreadLocal} reference.
95	 * This means that the spans -and hence the audit manager and
96	 * filesystem instances they refer to- are not retained by
97	 * long-lived threads once all other references to a span have been
98	 * released (HADOOP-18091).
99	 * The cost of this is that if garbage collection takes place before
100	 * a thread switches to a new span, the reference is lost; the
101	 * unbonded span is then handed back and the auditor notified through
102	 * {@code OperationAuditor.noteSpanReferenceLost()}.
103	 */
104	@InterfaceAudience.Private
105	public final class ActiveAuditManagerS3A
106	    extends CompositeService
107	    implements AuditManagerS3A {
108	
109	  /**
110	   * Logging.
111	   */
112	  private static final Logger LOG =
113	      LoggerFactory.getLogger(ActiveAuditManagerS3A.class);
114	
115	  /**
116	   * One of logger for warnings about span retrieval.
117	   */
118	  public static final LogExactlyOnce WARN_OF_SPAN_TYPE =
119	      new LogExactlyOnce(LOG);
120	
121	  public static final String AUDIT_MANAGER_OPERATION = "AuditManagerS3A";
122	
123	  public static final String NOT_A_WRAPPED_SPAN
124	      = "Span attached to request is not a wrapped span";
125	
126	  /**
127	   * Audit service.
128	   */
129	  private OperationAuditor auditor;
130	
131	  /**
132	   * Some basic analysis for the logs.
133	   */
134	  private final AWSRequestAnalyzer analyzer = new AWSRequestAnalyzer();
135	
136	  /**
137	   * This is the span returned to after a wrapper is closed or
138	   * the span is reset to the unbonded span..
139	   */
140	  private WrappingAuditSpan unbondedSpan;
141	
142	  /**
143	   * Thread local span. This defaults to being
144	   * the unbonded span.
145	   */
146	  private final WeakReferenceThreadMap<WrappingAuditSpan> activeSpanMap =
147	      new WeakReferenceThreadMap<>(
148	          (k) -> getUnbondedSpan(),
149	          this::noteSpanReferenceLost);
150	
151	  /**
152	   * Destination for recording statistics, especially duration/count of
153	   * operations.
154	   */
155	  private final IOStatisticsStore ioStatisticsStore;
156	
157	  /**
158	   * Instantiate.
159	   * @param iostatistics statistics target
160	   */
161	  public ActiveAuditManagerS3A(final IOStatisticsStore iostatistics) {
162	    super("ActiveAuditManagerS3A");
163	    this.ioStatisticsStore = iostatistics;
164	  }
165	
166	  @Override
167	  protected void serviceInit(final Configuration conf) throws Exception {
168	    super.serviceInit(conf);
169	    // create and register the service so it follows the same lifecycle
170	    OperationAuditorOptions options =
171	        OperationAuditorOptions.builder()
172	            .withConfiguration(conf)
173	            .withIoStatisticsStore(ioStatisticsStore);
174	    auditor = AuditIntegration.createAndInitAuditor(
175	        getConfig(),
176	        S3AAuditConstants.AUDIT_SERVICE_CLASSNAME,
177	        options);
178	    addService(auditor);
179	    LOG.debug("Audit manager initialized with audit service {}", auditor);
180	  }
181	
182	  /**
183	   * After starting the auditor, it is queried for its
184	   * unbonded span, which is then wrapped and stored for
185	   * use.
186	   */
187	  @Override
188	  protected void serviceStart() throws Exception {
189	    super.serviceStart();
190	    setUnbondedSpan(new WrappingAuditSpan(
191	        auditor.getUnbondedSpan(), false));
192	    LOG.debug("Started audit service {}", auditor);
193	  }
194	
195	  @Override
196	  public String toString() {
197	    final StringBuilder sb = new StringBuilder(super.toString());
198	    sb.append(", auditor=").append(auditor);
199	    sb.append('}');
200	    return sb.toString();
201	  }
202	
203	  @Override
204	  public OperationAuditor getAuditor() {
205	    return auditor;
206	  }
207	
208	  /**
209	   * Get the active span map, for testing.
210	   * @return the map of thread ID to active span.
211	   */
212	  @VisibleForTesting
213	  public WeakReferenceThreadMap<WrappingAuditSpan> getActiveSpanMap() {
214	    return activeSpanMap;
215	  }
216	
217	  /**
218	   * Prune the map of spans whose weak references have been
219	   * lost to garbage collection.
220	   * @return the number of entries pruned.
221	   */
222	  @VisibleForTesting
223	  public int prune() {
224	    return activeSpanMap.prune();
225	  }
226	
227	  /**
228	   * Span reference lost from GC operations.
229	   * This is only called when an attempt is made to retrieve on
230	   * the active thread or when a prune operation is cleaning up.
231	   *
232	   * @param threadId thread ID.
233	   */
234	  private void noteSpanReferenceLost(long threadId) {
235	    auditor.noteSpanReferenceLost(threadId);
236	  }
237	
238	  /**
239	   * Get the unbounded span. Until this manager
240	   * is fully initialized it will return the no-op
241	   * span.
242	   * @return the unbounded span.
243	   */
244	  private WrappingAuditSpan getUnbondedSpan() {
245	    return unbondedSpan;
246	  }
247	
248	  /**
249	   * Set the unbonded span.
250	   * @param unbondedSpan the new unbonded span
251	   */
252	  private void setUnbondedSpan(final WrappingAuditSpan unbondedSpan) {
253	    this.unbondedSpan = unbondedSpan;
254	  }
255	
256	  /**
257	   * Return the active wrapped span.
258	   * @return a span.
