70	  private static final Logger LOG =
71	      LoggerFactory.getLogger(TestActiveAuditManagerThreadLeakage.class);
72	
73	  /**
74	   * How many managers to sequentially create.
75	   */
76	  private static final int MANAGER_COUNT = 200;
77	
78	  /**
79	   * Size of the long-lived thread pool.
80	   */
81	  private static final int THREAD_COUNT = 20;
82	
83	  /**
84	   * How many spans to create in each audit manager.
85	   */
86	  private static final int SPAN_COUNT = THREAD_COUNT;
87	
88	  /**
89	   * The long-lived thread pool; the source of the leakage.
90	   */
91	  private ExecutorService workers;
92	
93	  /**
94	   * Count of prunings which took place in the manager teardowns.
95	   */
96	  private int pruneCount;
97	
98	  @After
99	  public void teardown() {
100	    if (workers != null) {
101	      workers.shutdownNow();
102	    }
103	  }
104	
105	  /**
106	   * Create and start an audit manager.
107	   * @param conf configuration to use.
108	   * @return a started audit manager.
109	   */
110	  private ActiveAuditManagerS3A createManager(Configuration conf) {
111	    ActiveAuditManagerS3A manager = new ActiveAuditManagerS3A(
112	        createIOStatisticsStoreForAuditing());
113	    manager.init(conf);
114	    manager.start();
115	    return manager;
116	  }
