118	  /**
119	   * The span map starts empty; creating a span adds an entry for the
120	   * current thread and deactivating it removes the entry again.
121	   */
122	  @Test
123	  public void testSpanMapLifecycle() throws Throwable {
124	    try (ActiveAuditManagerS3A manager = createManager(noopAuditConfig())) {
125	      final WeakReferenceThreadMap<?> spanMap = manager.getActiveSpanMap();
126	      assertThat(spanMap.size())
127	          .describedAs("initial size of %s", spanMap)
128	          .isEqualTo(0);
129	      final AuditSpan span = manager.createSpan("span", null, null);
130	      assertThat(spanMap.size())
131	          .describedAs("size of %s after span creation", spanMap)
132	          .isEqualTo(1);
133	      assertThat(spanMap.getForCurrentThread())
134	          .describedAs("active span in %s", spanMap)
135	          .isSameAs(span);
136	
137	      // a live span is never pruned.
138	      assertThat(manager.prune())
139	          .describedAs("prune count of %s with a live span", spanMap)
140	          .isEqualTo(0);
141	
142	      // deactivation removes the map entry.
143	      span.deactivate();
144	      assertThat(spanMap.size())
145	          .describedAs("size of %s after deactivation", spanMap)
146	          .isEqualTo(0);
