157	   * thread pool. If the spans are retained by the threads then this
158	   * will fail with an OutOfMemoryError.
159	   */
160	  @Test
161	  public void testMemoryLeak() throws Throwable {
162	    workers = Executors.newFixedThreadPool(THREAD_COUNT);
163	    for (int i = 0; i < MANAGER_COUNT; i++) {
164	      final long consumption = createAndTestOneAuditor();
165	      LOG.debug("manager {} memory retained {}", i, consumption);
166	    }
