171	  /**
172	   * Create, use and then shut down one audit manager.
173	   * @return the change in free memory.
174	   * @throws Exception failure
175	   */
176	  private long createAndTestOneAuditor() throws Exception {
177	    final long original = Runtime.getRuntime().freeMemory();
178	    try (ActiveAuditManagerS3A auditManager =
179	             createManager(memoryHungryAuditConfig())) {
180	
181	      // there is no guarantee that every thread of the pool is used,
182	      // so the thread IDs are collected from the results.
183	      final List<Future<Long>> futures = new ArrayList<>(SPAN_COUNT);
184	      final Callable<Long> operation = () -> spanningOperation(auditManager);
185	      for (int i = 0; i < SPAN_COUNT; i++) {
186	        futures.add(workers.submit(operation));
187	      }
188	      final Set<Long> threadIds = new HashSet<>();
189	      for (Future<Long> future : futures) {
190	        threadIds.add(future.get());
191	      }
