package org.apache.hadoop.util;

import java.util.ArrayList;
import java.util.List;

import org.junit.Before;
import org.junit.Test;

import org.apache.hadoop.test.AbstractHadoopTestBase;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Test {@link WeakReferenceMap}.
 *
 * There's no attempt to test the concurrency/GC behaviour here;
 * the loss of a reference is simulated by putting a null value
 * into the map, which is exactly what a garbage collected
 * weak reference resolves to.
 */
public class TestWeakReferenceMap extends AbstractHadoopTestBase {

  /**
   * Format of the strings created by the factory: {@value}.
   */
  public static final String FACTORY_STRING = "recreated-%d";

  /**
   * Map to test.
   */
  private WeakReferenceMap<Integer, String> referenceMap;

  /**
   * List of keys of the references reported as lost.
   */
  private List<Integer> lostReferences;

  @Before
  public void setup() {
    lostReferences = new ArrayList<>();
    referenceMap = new WeakReferenceMap<>(
        this::factory,
        this::referenceLost);
  }

  /**
   * Factory of new values; the key is included in the string
   * so that it can be correlated with the entry.
   * @param key key
   * @return a new instance.
   */
  private String factory(Integer key) {
    return String.format(FACTORY_STRING, key);
  }

  /**
   * Callback for lost references; adds the key to
   * {@link #lostReferences}.
   * @param key key of the lost reference.
   */
  private void referenceLost(Integer key) {
    lostReferences.add(key);
  }

  /**
   * Put, get, overwrite, remove and clear, all with
   * references which are never lost.
   */
  @Test
  public void testBasicOperationsWithValidReferences() {
    referenceMap.put(1, "1");
    referenceMap.put(2, "2");
    assertMapSize(2);
    assertMapContainsKey(1);
    assertMapEntryEquals(1, "1");
    assertMapEntryEquals(2, "2");

    // overwrite the entry; the old value is returned
    assertThat(referenceMap.put(1, "3"))
        .describedAs("previous value of key 1 in %s", referenceMap)
        .isEqualTo("1");
    assertMapEntryEquals(1, "3");

    // remove the entry
    assertThat(referenceMap.remove(1))
        .describedAs("value removed from %s", referenceMap)
        .isEqualTo("3");
    assertMapDoesNotContainKey(1);
    assertMapSize(1);

    // and a full clear
    referenceMap.clear();
    assertMapSize(0);

    // nothing was ever lost
    assertNoReferencesLost();
    assertThat(referenceMap.getEntriesCreatedCount())
        .describedAs("entries created count of %s", referenceMap)
        .isEqualTo(0);
  }

  /**
   * A get of an unknown key demand creates the entry through
   * the factory.
   */
  @Test
  public void testEntryDemandCreation() {
    assertMapEntryEquals(1, factory(1));
    assertMapSize(1);
    assertMapContainsKey(1);
    // and the entry created counter is incremented
    assertThat(referenceMap.getEntriesCreatedCount())
        .describedAs("entries created count of %s", referenceMap)
        .isEqualTo(1);
    // no reference was lost, it just never existed.
    assertNoReferencesLost();
  }

  /**
   * A null value in the map is the same as a reference which
   * has been garbage collected: it is not "contained", and a
   * {@code get()} will report the loss and create a new entry.
   */
  @Test
  public void testGetOfLostReference() {
    // put a null value in; this is the same as a lost reference
    referenceMap.put(1, null);
    assertMapSize(1);
    assertMapDoesNotContainKey(1);
    assertNoReferencesLost();

    // a get() reports the loss and creates a new entry
    assertMapEntryEquals(1, factory(1));
    assertReferencesLost(1);
    assertMapSize(1);
    assertMapContainsKey(1);

    // a second get() returns the new entry; no more losses
    assertMapEntryEquals(1, factory(1));
    assertReferencesLost(1);
    assertThat(referenceMap.getEntriesCreatedCount())
        .describedAs("entries created count of %s", referenceMap)
        .isEqualTo(1);
  }

  /**
   * Pruning removes all lost references, and reports each one.
   */
  @Test
  public void testPruneLostReferences() {
    referenceMap.put(1, "1");
    referenceMap.put(2, null);
    referenceMap.put(3, null);
    assertMapSize(3);

    assertThat(referenceMap.prune())
        .describedAs("number of entries pruned from %s", referenceMap)
        .isEqualTo(2);
    assertMapSize(1);
    assertMapEntryEquals(1, "1");
    assertMapDoesNotContainKey(2);
    assertMapDoesNotContainKey(3);
    assertReferencesLost(2, 3);

    // and a second prune is a no-op
    assertThat(referenceMap.prune())
        .describedAs("number of entries pruned from %s", referenceMap)
        .isEqualTo(0);
    assertReferencesLost(2, 3);
  }

  /**
   * A map with no reference lost callback is safe to use.
   */
  @Test
  public void testNoReferenceLostCallback() {
    WeakReferenceMap<Integer, String> map =
        new WeakReferenceMap<>(this::factory, null);
    map.put(1, null);
    assertThat(map.get(1))
        .describedAs("value of key 1 in %s", map)
        .isEqualTo(factory(1));
    assertThat(map.getReferenceLostCount())
        .describedAs("reference lost count of %s", map)
        .isEqualTo(1);
  }

  /**
   * Assert that the map has the given size.
   * @param size expected size.
   */
  private void assertMapSize(int size) {
    assertThat(referenceMap.size())
        .describedAs("size of %s", referenceMap)
        .isEqualTo(size);
  }

  /**
   * Assert that the map has a valid reference under the key.
   * @param key key to look up.
   */
  private void assertMapContainsKey(int key) {
    assertThat(referenceMap.containsKey(key))
        .describedAs("%s contains key %d", referenceMap, key)
        .isTrue();
  }

  /**
   * Assert that the map has no valid reference under the key.
   * @param key key to look up.
   */
  private void assertMapDoesNotContainKey(int key) {
    assertThat(referenceMap.containsKey(key))
        .describedAs("%s contains key %d", referenceMap, key)
        .isFalse();
  }

  /**
   * Assert that a {@code get()} of the key returns the
   * expected value.
   * @param key key to look up.
   * @param value expected value.
   */
  private void assertMapEntryEquals(int key, String value) {
    assertThat(referenceMap.get(key))
        .describedAs("value of key %d in %s", key, referenceMap)
        .isEqualTo(value);
  }

  /**
   * Assert that the sequence of lost references is as expected,
   * and that the loss counter matches.
   * @param keys expected keys of lost references.
   */
  private void assertReferencesLost(Integer... keys) {
    assertThat(lostReferences)
        .describedAs("references lost in %s", referenceMap)
        .containsExactly(keys);
    assertThat(referenceMap.getReferenceLostCount())
        .describedAs("reference lost count of %s", referenceMap)
        .isEqualTo(keys.length);
  }

  /**
   * Assert that no references have been reported as lost.
   */
  private void assertNoReferencesLost() {
    assertReferencesLost();
  }

}

